xpath.script:
            (function() {
                // Function to get cookie value
                function getCookie(name) {
                    const value = `; ${document.cookie}`;
                    const parts = value.split(`; ${name}=`);
                    if (parts.length === 2) return parts.pop().split(';').shift();
                }

                // Check if we're on the confirmation page
                const currentPath = window.location.pathname;
                if (currentPath === '/shop/confirmation') {

                    // Check logo preference cookie
                    const logoPreference = getCookie('logo_preference');

                    if (logoPreference === 'flow_logo') {
                        console.log('Flow logo detected - redirecting in 15 seconds...');

                        // Countdown timer variables
                        let secondsLeft = 15;
                        let redirectTimeout;
                        let countdownInterval;
                        let isCancelled = false;

                        // Create countdown notification
                        const redirectMessage = document.createElement('div');
                        redirectMessage.id = 'redirect-countdown';

                        // Function to update countdown display
                        function updateCountdown() {
                            const countdownElement = document.getElementById('countdown');
                            if (countdownElement && !isCancelled) {
                                countdownElement.textContent = secondsLeft;
                            }
                        }

                        // Initial HTML
                        redirectMessage.innerHTML = `

✓ Order Confirmed!

You will be redirected to Home Page in ${secondsLeft}s
                            Stay on This Page
                        `;

                        document.body.appendChild(redirectMessage);

                        // Start countdown
                        function startCountdown() {
                            countdownInterval = setInterval(function() {
                                if (!isCancelled) {
                                    secondsLeft--;
                                    updateCountdown();

                                    if (secondsLeft <= 0) {
                                        clearInterval(countdownInterval);
                                    }
                                }
                            }, 1000);
                        }

                        // Set redirect timeout
                        function setRedirectTimeout() {
                            redirectTimeout = setTimeout(function() {
                                if (!isCancelled) {
                                    window.location.href = 'https://www.flowacademy.mt/';
                                }
                            }, 15000); // 15000 milliseconds = 15 seconds
                        }

                        // Cancel redirect function
                        function cancelRedirect() {
                            isCancelled = true;
                            clearTimeout(redirectTimeout);
                            clearInterval(countdownInterval);

                            // Update message
                            const messageDiv = document.getElementById('redirect-countdown');
                            if (messageDiv) {
                                messageDiv.innerHTML = `

✓ Redirect Cancelled

You can continue browsing this site.
                                `;

                                // Remove notification after 3 seconds
                                setTimeout(function() {
                                    messageDiv.style.animation = 'slideOut 0.5s ease-in';
                                    setTimeout(function() {
                                        if (messageDiv && messageDiv.parentNode) {
                                            messageDiv.parentNode.removeChild(messageDiv);
                                        }
                                    }, 500);
                                }, 3000);
                            }
                        }

                        // Add slideOut animation
                        const style = document.createElement('style');
                        style.textContent = `
                            @keyframes slideOut {
                                from {
                                    transform: translateX(0);
                                    opacity: 1;
                                }
                                to {
                                    transform: translateX(400px);
                                    opacity: 0;
                                }
                            }
                        `;
                        document.head.appendChild(style);

                        // Wait a moment for DOM to be ready, then attach event listener
                        setTimeout(function() {
                            const cancelBtn = document.getElementById('cancel-redirect');
                            if (cancelBtn) {
                                cancelBtn.addEventListener('click', function(e) {
                                    e.preventDefault();
                                    e.stopPropagation();
                                    cancelRedirect();
                                });
                            }
                        }, 100);

                        // Start the countdown and redirect timer
                        startCountdown();
                        setRedirectTimeout();
                    }
                }
            })();
